--
-- Table structure for table `secondhand_subscription`
--

DROP TABLE IF EXISTS `secondhand_subscription`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `secondhand_subscription` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '订阅用户ID',
  `keyword` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订阅关键词',
  `category` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '可选分类',
  `max_price` decimal(10,2) DEFAULT NULL COMMENT '预算上限',
  `campus` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '校区偏好',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '状态: ACTIVE/INACTIVE',
  `last_notified_at` datetime DEFAULT NULL COMMENT '最近提醒时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_sub_user` (`user_id`),
